import test from 'node:test';import assert from 'node:assert/strict';import vm from 'node:vm';import {execFileSync} from 'node:child_process';
import {assertRecommendationContract,assertSelectedContracts,assertTopProjection,independentSelection,recommendationPrefix} from './recommendation_contract.mjs';
const BASE='b12e20c1b6d856a021898a0c1c9221b30393a221',HEAD='519b4bd18a55bb11ed8e0f6a53e18e691b5afc82';
const r=JSON.parse(execFileSync(process.execPath,['.github/scripts/compare_p1s_recommendation.mjs',BASE,HEAD],{encoding:'utf8',maxBuffer:1<<28}));
const original=execFileSync('git',['show',HEAD+':.github/scripts/publication_ci_signatures.mjs'],{encoding:'utf8'});
const body=original.slice(original.indexOf('for(const flag'));
function oldGate(result){vm.runInNewContext(body,{assert,result,baseline:BASE,exact:HEAD,summary:{conditions:{}},console:{log(){}}});}
function newGate(result){for(const f of ['withSightings','withoutSightings'])assertRecommendationContract(result.out[BASE][f],result.out[HEAD][f],f);const x=result.out[BASE].syntheticNullScores,y=result.out[HEAD].syntheticNullScores;assert.deepEqual(y.candidateContracts,x.candidateContracts);assert.deepEqual(y.zeroScoreCandidates,x.zeroScoreCandidates);assert.deepEqual(y.nulledSiteIds,x.nulledSiteIds);assert.ok(y.candidateContracts.every(e=>!y.nulledSiteIds.includes(e.id)));assertSelectedContracts(x.candidateContracts,y.topContracts,10);assertTopProjection(y.top,y.topContracts,{synthetic:true});}
const mutations={date:q=>q.out[HEAD].withSightings.top[0].date='2099-01-01',time:q=>q.out[HEAD].withSightings.top[0].time='99:99',unknownId:q=>q.out[HEAD].withSightings.top[0].id='999999',duplicate:q=>q.out[HEAD].withSightings.top[1].id=q.out[HEAD].withSightings.top[0].id,mandatory:q=>q.out[HEAD].withSightings.top[0].mandatory=!q.out[HEAD].withSightings.top[0].mandatory,notice:q=>q.out[HEAD].withSightings.top[0].reasons='removed',tide:q=>q.out[HEAD].withSightings.top[0].tide='wrong tide',syntheticZero:q=>q.out[HEAD].syntheticNullScores.zeroScoreCandidates.push('999999'),syntheticId:q=>q.out[HEAD].syntheticNullScores.top[0].id='999999'};
test('normal P1-S176 contract allows verified B ID replacements and per-ID dates',()=>{oldGate(r);newGate(r);for(const f of ['withSightings','withoutSightings'])assert.equal(r.out[HEAD][f].candidates,176);assert.ok(r.out[HEAD].withoutSightings.top.some((e,i)=>String(e.id)!==String(r.out[BASE].withoutSightings.top[i].id)));});
for(const [name,mutate] of Object.entries(mutations))test('negative control '+name+': old gate accepted, strict gate rejects',()=>{const q=structuredClone(r);mutate(q);assert.doesNotThrow(()=>oldGate(q));assert.throws(()=>newGate(q));});
for(const field of ['date','time','score','rank','bonus','priority','mandatory','selectedAxis','safe','eligible','sortLevel','axes','recent','weather','sample','cautionText','weatherText','label'])test('same-ID contract rejects changed '+field,()=>{const q=structuredClone(r.out[HEAD].withSightings);q.topContracts[0][field]=field==='axes'?{other:true}:field==='recent'?{ageDays:0,speciesCount:99}:field==='weather'||field==='sample'?null:field==='safe'||field==='eligible'?false:field==='mandatory'?!q.topContracts[0][field]:'tampered';assert.throws(()=>assertRecommendationContract(r.out[BASE].withSightings,q));});
test('candidate membership/core/type/region constraints cannot be erased',()=>{for(const field of ['autumnCore','winterCore','springCore','axes','region','rule','date']){const q=structuredClone(r.out[HEAD].withSightings);q.candidateContracts[0][field]='tampered';assert.throws(()=>assertRecommendationContract(r.out[BASE].withSightings,q));}});
function row(id,region,extra={}){return {id:String(id),name:'synthetic',region,rule:'general_birding',score:92,displayScore:92,rank:108,bonus:16,recent:{ageDays:0,speciesCount:4,bonus:16},date:'2027-10-15',time:'09:00',season:'autumn',axes:{field:true},priority:4,mandatory:false,sortLevel:0,autumnCore:false,winterCore:false,springCore:false,springGeolmaeriPriority:false,eligible:true,safe:true,pelagicSafe:true,reasons:[],tide:'',basis:'synthetic',weather:{score:92},sample:{score:92},...extra};}
for(const month of [10,12,5,6,7])test('all-season independent prefix respects date/recent/core and stable ID '+month,()=>{const season=month===10?'autumn':month===12?'winter':month===5?'spring':'summer',axis=season==='autumn'||season==='winter'?'field':season==='spring'?'island':'forest',pool=[row(101,'인천',{season,axes:{[axis]:true}}),row(102,'인천',{season,axes:{[axis]:true}}),row(103,'제주',{season,axes:{[axis]:true}})];const got=independentSelection(pool,month);assert.deepEqual(got.map(e=>e.id),['101','103','102']);assert.deepEqual(independentSelection(pool.slice().reverse(),month),got);assertSelectedContracts(pool,got,month);for(const change of [{date:'2027-10-16'},{recent:{ageDays:1,speciesCount:4}},{rank:107,bonus:15}]){const a=pool[0],b={...pool[1],...change};assert.ok(recommendationPrefix(a,b,season,axis)<0,'equal triple is not enough for date/recent');}});
test('autumn notice priority and tide level precede regional diversity',()=>{const a=row(101,'인천',{axes:{mudflat:true},priority:1,mandatory:true}),b=row(102,'제주',{axes:{mudflat:true},priority:4});assert.ok(recommendationPrefix(a,b,'autumn','mudflat')<0);assert.ok(recommendationPrefix({...a,sortLevel:900},{...a,id:'102',sortLevel:860},'autumn','mudflat')<0);});
